export function ensureLayers(c){
 c.guideOpacity=Number.isFinite(c.guideOpacity)?Math.max(0,Math.min(100,c.guideOpacity)):100;
 c.paintLayers??=c.strokes?.length?[{id:'rough',name:'선화 1',opacity:100,visible:true,locked:false}]:defaultLayers();c.layerGroups??={};
 c.layerSettings??={};for(const key of ['background','guide','text'])c.layerSettings[key]??={opacity:100,visible:true,locked:key!=='text'};
 c.activeLayer??=c.paintLayers[0]?.id||'rough';return c;
}
// Choose an opaque, untinted drawing layer without recoloring existing artwork.
export function preparePencilLayer(c){
 ensureLayers(c);
 const usable=l=>l&&l.opacity===100&&!l.displayColor&&!l.outline&&layerVisible(c,l)&&!l.locked;
 let layer=c.paintLayers.find(l=>l.id===c.activeLayer);
 if(!usable(layer))layer=c.paintLayers.find(l=>l.name==='콘티 펜슬'&&usable(l));
 if(!layer){if(c.paintLayers.length>=30)throw Error('진한 펜슬용 레이어를 만들 공간이 없습니다. 레이어를 정리하거나 불투명도 100%의 일반 레이어를 선택하세요.');layer={id:crypto.randomUUID(),name:'콘티 펜슬',group:'콘티',opacity:100,visible:true,locked:false};c.paintLayers.push(layer);c.layerGroups['콘티']={...c.layerGroups['콘티'],visible:true};}
 c.activeLayer=layer.id;return layer;
}
export function activePaint(c){ensureLayers(c);return c.paintLayers.find(l=>l.id===c.activeLayer);}
export const layerVisible=(c,l)=>l.visible&&c.layerGroups?.[l.group]?.visible!==false;
export const layerStrokes=(c,id)=>{const l=c.paintLayers.find(l=>l.id===id);return c.strokes.filter(s=>(s.layerId||'rough')===id).map(s=>({...s,color:l?.displayColor||s.color,layerOutline:l?.outline,outlineWidth:l?.outlineWidth}));};
