 const notice=document.createElement('div');notice.id='paintAppearanceNotice';notice.setAttribute('role','status');const brushPane=$('drawingTools');(brushPane||box).append(notice);
 function appearanceStatus(){coloring.update();const c=selectedCut(),l=c&&activePaint(c);appearance.hidden=!l;if(!l){notice.hidden=true;return;}$('layerColorEnabled').checked=!!l.displayColor;$('layerDisplayColor').value=l.displayColor||'#78a6dc';$('layerDisplayColor').disabled=!l.displayColor;notice.hidden=!l.displayColor&&l.opacity===100;notice.textContent=l.name+' · '+(l.displayColor?'표시색 '+l.displayColor+' 적용 · ':'')+l.opacity+'%';notice.title='레이어 팔레트에서 표시색을 끄거나 «펜 색상 그대로 · 100%»를 누르세요. 저장된 선의 색은 바뀌지 않습니다.';}
 const changeAppearance=fn=>{const c=selectedCut(),l=c&&activePaint(c);if(!l||l.locked)return toast('잠기지 않은 그리기 레이어를 선택하세요.');checkpoint();fn(l);render();repaint();};
