 function repaint(){const c=selectedCut();if(c)redraw(c);appearanceStatus();save();}
 const master=$('guideOpacity');let masterChanging=false;master.onpointerdown=()=>{checkpoint();masterChanging=true;};master.oninput=()=>{const c=selectedCut();if(!c)return;ensureLayers(c);if(!masterChanging){checkpoint();masterChanging=true;}c.guideOpacity=+master.value;$('guideOpacityValue').textContent=master.value+'%';repaint();};master.onchange=()=>{masterChanging=false;};
 const bg=$('bgOpacity');bg.onpointerdown=()=>{checkpoint();dragCheckpoint=true;};bg.oninput=()=>{const c=selectedCut();if(!c)return;ensureLayers(c);if(!dragCheckpoint){checkpoint();dragCheckpoint=true;}c.layerSettings.background.opacity=+bg.value;$('bgOpacityValue').textContent=bg.value+'%';repaint();};bg.onchange=()=>{dragCheckpoint=false;render();};
 const coloring=setupColoringUI({box,getProject,selectedCut,checkpoint,save,redraw,render,setTool,toast});
